import json
import re

allowed_labels = sorted(df_clean[label_col].astype(str).unique())

def row_to_text(row):
    active = []
    for col, val in row.items():
        if val == 1:
            active.append(col)
        elif val not in (0, 1):
            active.append(f"{col}={val}")
    return ", ".join(active) if active else "No symptoms"

def build_prompt(symptoms):
    return f"""
Choose exactly ONE disease from this list:
{', '.join(allowed_labels)}

Symptoms:
{symptoms}

Return ONLY valid JSON with no markdown fences and no extra text.
Format:
{{"predicted_disease": "...", "reasoning": "..."}}
"""

def extract_json(text):
    text = text.strip()

    # remove markdown fences
    text = re.sub(r"^```json\s*", "", text, flags=re.IGNORECASE)
    text = re.sub(r"^```\s*", "", text)
    text = re.sub(r"\s*```$", "", text)

    # direct parse
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        pass

    # fallback: extract JSON block
    match = re.search(r"\{.*\}", text, flags=re.DOTALL)
    if match:
        return json.loads(match.group(0))

    raise ValueError("No valid JSON found")

def normalize_prediction(pred, allowed_labels):
    pred = str(pred).strip()

    # exact match
    if pred in allowed_labels:
        return pred

    # case-insensitive fallback
    allowed_map = {label.lower(): label for label in allowed_labels}
    if pred.lower() in allowed_map:
        return allowed_map[pred.lower()]

    return "INVALID_LABEL"

# --------------------------------------------------
# 1. Get Gemini predictions once on X_test
# --------------------------------------------------

y_true_labels = []
y_pred_labels = []
reasoning_list = []
raw_output_list = []

correct = 0
total = 0

for i, (_, row) in enumerate(X_test.iterrows()):
    symptoms = row_to_text(row)

    # y_test is a pandas Series, so use iloc
    true_label_encoded = y_test.iloc[i]
    true_label = le.inverse_transform([true_label_encoded])[0]

    prompt = build_prompt(symptoms)

    response = client.models.generate_content(
        model="gemini-3.1-pro-preview",
        contents=prompt
    )

    text = response.text.strip()
    raw_output_list.append(text)

    try:
        data = extract_json(text)
        pred = data.get("predicted_disease", "").strip()
        reasoning = data.get("reasoning", "")
        pred = normalize_prediction(pred, allowed_labels)
    except Exception as e:
        pred = "PARSE_ERROR"
        reasoning = f"{str(e)} | Raw output: {text[:300]}"

    y_true_labels.append(true_label)
    y_pred_labels.append(pred)
    reasoning_list.append(reasoning)

    is_correct = (pred == true_label)
    if is_correct:
        correct += 1

    total += 1
    print(f"\nExample {i+1}")
    print("Symptoms:", symptoms[:200])
    print("True:", true_label)
    print("Pred:", pred)
    print("Correct:", is_correct)
    print("Reasoning:", reasoning[:150])
    if (i + 1) % 50 == 0:
      print(f"Processed {i+1}/{len(X_test)} samples...")
      results_df = pd.DataFrame({
          "y_true": y_true_labels,
          "y_pred": y_pred_labels,
          "reasoning": reasoning_list,
          "raw_output": raw_output_list
          })
      results_df.to_csv("gemini_test_predictions.csv", index=False)



# --------------------------------------------------
