# ============================================================
# 2. HELPER FUNCTION: BOOTSTRAP METRICS FROM SAVED PREDICTIONS
# ============================================================

def bootstrap_from_predictions(y_true, y_pred, n_bootstrap=500, random_state=42):
    rng = np.random.default_rng(random_state)

    y_true = np.array(y_true)
    y_pred = np.array(y_pred)

    n = len(y_true)
    bootstrap_accuracies = []
    bootstrap_macro_f1s = []

    for _ in range(n_bootstrap):
        idx = rng.choice(n, size=n, replace=True)

        y_true_boot = y_true[idx]
        y_pred_boot = y_pred[idx]

        acc = accuracy_score(y_true_boot, y_pred_boot)
        f1 = f1_score(y_true_boot, y_pred_boot, average="macro", zero_division=0)

        bootstrap_accuracies.append(acc)
        bootstrap_macro_f1s.append(f1)

    return {
        "bootstrap_accuracies": bootstrap_accuracies,
        "bootstrap_macro_f1s": bootstrap_macro_f1s,
        "bootstrap_mean_accuracy": np.mean(bootstrap_accuracies),
        "bootstrap_sd_accuracy": np.std(bootstrap_accuracies, ddof=1),
        "bootstrap_mean_macro_f1": np.mean(bootstrap_macro_f1s),
        "bootstrap_sd_macro_f1": np.std(bootstrap_macro_f1s, ddof=1),
    }

# ============================================================
# 3. GET SUPERVISED MODEL PREDICTIONS + BOOTSTRAP THEM
# ============================================================

